typedef struct { size_t size; int full; unsigned char data[512]; } queue_t;
static queue_t queues[3]; static unsigned nq;
static jmp_buf done_worker;
static int saves, writes, connects, scan_stops, clear_calls, reject_queue, scan_case, mode_error, config_error, nvs_error;
static uint16_t mock_count; static wifi_ap_record_t mock_records[20];
static zam_config_wifi_t disk;
static int64_t fake_time;
size_t strlcpy(char *d,const char *s,size_t n) { size_t l=strlen(s); if(n) {size_t c=l<n-1?l:n-1;memcpy(d,s,c);d[c]=0;} return l; }
size_t heap_caps_get_free_size(int x){(void)x;return 0;} size_t heap_caps_get_largest_free_block(int x){(void)x;return 0;} size_t heap_caps_get_minimum_free_size(int x){(void)x;return 0;}
const char *esp_err_to_name(esp_err_t e){(void)e;return "error";} int64_t esp_timer_get_time(void){return fake_time;}
QueueHandle_t xQueueCreate(unsigned n,size_t s){(void)n;assert(nq<3 && s<=sizeof(queues[0].data));queue_t *q=&queues[nq++];q->size=s;return q;}
int xQueueSend(QueueHandle_t h,const void *p,unsigned t){(void)t;queue_t *q=h;if(reject_queue || q->full)return 0;memcpy(q->data,p,q->size);q->full=1;return 1;}
int xQueueOverwrite(QueueHandle_t h,const void *p){queue_t *q=h;memcpy(q->data,p,q->size);q->full=1;return 1;}
int xQueueReceive(QueueHandle_t h,void *p,unsigned t){queue_t *q=h;if(q->full){memcpy(p,q->data,q->size);q->full=0;return 1;}if(h==jobs && t)longjmp(done_worker,1);return 0;}
void vQueueDelete(QueueHandle_t h){(void)h;} static pthread_mutex_t mock_mutex=PTHREAD_MUTEX_INITIALIZER; SemaphoreHandle_t xSemaphoreCreateMutex(void){return &mock_mutex;} int xSemaphoreTake(SemaphoreHandle_t h,unsigned t){(void)t;return pthread_mutex_lock(h)==0;} int xSemaphoreGive(SemaphoreHandle_t h){return pthread_mutex_unlock(h)==0;} void vSemaphoreDelete(SemaphoreHandle_t h){(void)h;} int xTaskCreate(void (*f)(void *),const char *n,unsigned s,void *a,int p,void *o){(void)f;(void)n;(void)s;(void)a;(void)p;(void)o;return 1;}
esp_err_t zam_config_wifi_load(zam_config_wifi_t *o){if(!disk.version)return ESP_ERR_NVS_NOT_FOUND;*o=disk;return ESP_OK;} esp_err_t zam_config_wifi_save(const zam_config_wifi_t *i){saves++;if(nvs_error)return ESP_FAIL;disk=*i;return ESP_OK;}
esp_err_t esp_read_mac(uint8_t *m,int x){(void)x;memset(m,1,6);return 0;} esp_err_t esp_netif_init(void){return 0;} esp_err_t esp_event_loop_create_default(void){return 0;} esp_err_t esp_event_loop_delete_default(void){return 0;} static esp_netif_t netif; esp_netif_t *esp_netif_create_default_wifi_ap(void){return &netif;} esp_netif_t *esp_netif_create_default_wifi_sta(void){return &netif;} void esp_netif_destroy_default_wifi(esp_netif_t *n){(void)n;} esp_err_t esp_netif_get_ip_info(esp_netif_t *n,esp_netif_ip_info_t *i){(void)n;(void)i;return 0;}
esp_err_t esp_event_handler_register(int b,int i,void (*f)(void *,int,int32_t,void *),void *a){(void)b;(void)i;(void)f;(void)a;return 0;} esp_err_t esp_event_handler_unregister(int b,int i,void (*f)(void *,int,int32_t,void *)){(void)b;(void)i;(void)f;return 0;}
esp_err_t esp_wifi_init(const wifi_init_config_t *i){(void)i;return 0;} esp_err_t esp_wifi_deinit(void){return 0;} esp_err_t esp_wifi_set_storage(int s){(void)s;return 0;} esp_err_t esp_wifi_set_mode(wifi_mode_t m){(void)m;writes++;return mode_error?ESP_FAIL:0;} esp_err_t esp_wifi_set_config(int i,const wifi_config_t *c){(void)i;(void)c;writes++;return config_error?ESP_FAIL:0;} esp_err_t esp_wifi_start(void){return 0;} esp_err_t esp_wifi_stop(void){return 0;} esp_err_t esp_wifi_connect(void){connects++;return 0;} esp_err_t esp_wifi_disconnect(void){return 0;} esp_err_t esp_wifi_ap_get_sta_list(wifi_sta_list_t *s){s->num=0;return 0;}
esp_err_t esp_wifi_scan_start(const wifi_scan_config_t *c,bool block){assert(c->show_hidden && !block);if(scan_case==2)return ESP_FAIL;if(scan_case!=1){wifi_event_sta_scan_done_t e={.status=scan_case==3};event_cb(NULL,WIFI_EVENT,WIFI_EVENT_SCAN_DONE,&e);}return 0;} esp_err_t esp_wifi_scan_stop(void){scan_stops++;return 0;} esp_err_t esp_wifi_clear_ap_list(void){clear_calls++;return 0;} esp_err_t esp_wifi_scan_get_ap_records(uint16_t *n,wifi_ap_record_t *r){if(*n>mock_count)*n=mock_count;memcpy(r,mock_records,*n*sizeof(*r));return 0;}
static void run(void){if(!setjmp(done_worker))work(NULL);}
static void reset(void){memset(queues,0,sizeof(queues));nq=0;started=ever_init=command_busy=scan_quarantine=false;highest_operation_id=0;memset(&operation,0,sizeof(operation));memset(&status,0,sizeof(status));memset(&cfg,0,sizeof(cfg));memset(&disk,0,sizeof(disk));saves=writes=connects=scan_stops=clear_calls=reject_queue=scan_case=mode_error=config_error=nvs_error=mock_count=0;fake_time=0;assert(zam_wifi_init()==ESP_OK);writes=0;}
static zam_wifi_operation_t get(uint32_t id){zam_wifi_operation_t o;assert(zam_wifi_operation(id,&o)==0);return o;}
static zam_wifi_sta_request_t request(uint32_t id){return (zam_wifi_sta_request_t){.id=id,.enabled=true,.ssid="network",.password_action=ZAM_WIFI_PASSWORD_REPLACE,.password="password"};}
