 reset();zam_wifi_sta_request_t r=request(1);assert(zam_wifi_configure_sta(&r)==0);run();r.id=2;r.enabled=false;assert(zam_wifi_configure_sta(&r)==0);run();assert(!strcmp(disk.sta_ssid,"network")&&!strcmp(disk.sta_password,"password"));assert(disk.mode==ZAM_WIFI_AP);int before=connects;request_attempt();assert(connects==before);r.id=3;r.enabled=true;r.ssid="other";r.password_action=ZAM_WIFI_PASSWORD_KEEP;assert(zam_wifi_configure_sta(&r)==0);run();assert(!strcmp(disk.sta_password,"password"));r.id=4;r.password_action=ZAM_WIFI_PASSWORD_OPEN;assert(zam_wifi_configure_sta(&r)==0);run();assert(!disk.sta_password[0]);assert(zam_wifi_configure_sta(&(zam_wifi_sta_request_t){.id=2})==ESP_ERR_INVALID_STATE);
 r.id=5;r.enabled=false;assert(zam_wifi_configure_sta(&r)==0);run();zam_config_wifi_t persisted=disk;memset(queues,0,sizeof(queues));nq=0;ever_init=started=command_busy=scan_quarantine=false;memset(&status,0,sizeof(status));memset(&cfg,0,sizeof(cfg));assert(zam_wifi_init()==0);assert(!memcmp(&cfg,&persisted,sizeof(cfg)) && status.configured==ZAM_WIFI_AP && status.effective==ZAM_WIFI_AP);before=connects;request_attempt();assert(connects==before);
 reset();r=request(1);assert(zam_wifi_configure_sta(&r)==0);run();zam_config_wifi_t old=disk;int old_writes=writes;r.id=2;r.ssid="new";nvs_error=1;assert(zam_wifi_configure_sta(&r)==0);run();assert(get(2).persistence==ZAM_WIFI_PERSIST_FAILED && get(2).application==ZAM_WIFI_APPLY_NOT_ATTEMPTED && !memcmp(&old,&disk,sizeof(disk)) && !memcmp(&old,&cfg,sizeof(cfg)) && writes==old_writes);
 reset();r=request(1);config_error=1;assert(zam_wifi_configure_sta(&r)==0);run();assert(get(1).persistence==ZAM_WIFI_PERSIST_SAVED && get(1).application==ZAM_WIFI_APPLY_FAILED && status.paused);
 reset();r=request(1);mode_error=1;assert(zam_wifi_configure_sta(&r)==0);run();assert(get(1).persistence==ZAM_WIFI_PERSIST_SAVED && get(1).application==ZAM_WIFI_APPLY_FAILED && disk.version && status.paused);
 reset();r=request(1);assert(zam_wifi_configure_sta(&r)==0);run();ip_event_got_ip_t ip={0};event_cb(NULL,IP_EVENT,IP_EVENT_STA_GOT_IP,&ip);run();assert(get(1).connection==ZAM_WIFI_CONNECTION_CONNECTED);wifi_event_sta_disconnected_t down={.reason=42};event_cb(NULL,WIFI_EVENT,WIFI_EVENT_STA_DISCONNECTED,&down);run();assert(get(1).connection==ZAM_WIFI_CONNECTION_NOT_CONNECTED && get(1).disconnect_reason==42);assert(zam_wifi_disconnect()==0);run();assert(get(1).superseded);
 reset();r=request(1);reject_queue=1;assert(zam_wifi_configure_sta(&r)==ESP_ERR_NO_MEM);reject_queue=0;assert(zam_wifi_configure_sta(&r)==0);run();assert(zam_wifi_operation(9,&operation)==ESP_ERR_NOT_FOUND);
 reset();r=request(1);r.password_action=ZAM_WIFI_PASSWORD_KEEP;assert(zam_wifi_configure_sta(&r)==ESP_ERR_INVALID_STATE);r.password_action=ZAM_WIFI_PASSWORD_REPLACE;r.ssid="";assert(zam_wifi_configure_sta(&r)==ESP_ERR_INVALID_ARG);r.ssid="bad\nssid";assert(zam_wifi_configure_sta(&r)==ESP_ERR_INVALID_ARG);r.ssid="ssid";r.password="bad\npass";assert(zam_wifi_configure_sta(&r)==ESP_ERR_INVALID_ARG);assert(zam_wifi_set_sta("serial","password")==ESP_OK);assert(zam_wifi_configure_sta(&r)==ESP_ERR_INVALID_ARG);r.password="password";assert(zam_wifi_configure_sta(&r)==ESP_ERR_INVALID_STATE);run();assert(!strcmp(disk.sta_ssid,"serial"));
