static void scan_test(void){reset();uint32_t id;assert(zam_wifi_scan_start(&id)==0 && id==1);uint32_t other;assert(zam_wifi_scan_start(&other)==ESP_ERR_INVALID_STATE);zam_wifi_sta_request_t r=request(1);assert(zam_wifi_configure_sta(&r)==ESP_ERR_INVALID_STATE);mock_count=20;mock_records[0].ssid[0]=0xff;mock_records[0].authmode=WIFI_AUTH_OPEN;mock_records[1].ssid[0]=0;mock_records[1].authmode=WIFI_AUTH_WPA2_PSK;strcpy((char *)mock_records[2].ssid,"duplicate");strcpy((char *)mock_records[3].ssid,"duplicate");mock_records[2].rssi=-20;mock_records[3].rssi=-80;run();zam_wifi_scan_item_t out[20];size_t count;bool pending;assert(zam_wifi_scan_get(id,out,20,&count,&pending)==0 && !pending && count==20 && (unsigned char)out[0].ssid[0]==0xff && !out[1].ssid[0] && out[0].auth==WIFI_AUTH_OPEN && out[1].auth==WIFI_AUTH_WPA2_PSK && !strcmp(out[2].ssid,out[3].ssid) && out[2].rssi!=out[3].rssi);assert(saves==0);mock_count=0;assert(zam_wifi_scan_start(&other)==0);run();assert(zam_wifi_scan_get(other,out,20,&count,&pending)==0 && count==0);scan_case=3;assert(zam_wifi_scan_start(&other)==0);run();assert(zam_wifi_scan_get(other,out,20,&count,&pending)==ESP_FAIL);scan_case=1;assert(zam_wifi_scan_start(&id)==0);run();assert(zam_wifi_scan_get(id,out,20,&count,&pending)==ESP_ERR_TIMEOUT && !pending && scan_stops==1);assert(zam_wifi_scan_start(&other)==ESP_ERR_INVALID_STATE);wifi_event_sta_scan_done_t late={0};event_cb(NULL,WIFI_EVENT,WIFI_EVENT_SCAN_DONE,&late);scan_drain_late();assert(clear_calls && zam_wifi_scan_start(&other)==0);scan_case=2;run();assert(zam_wifi_scan_get(other,out,20,&count,&pending)==ESP_FAIL);assert(zam_wifi_scan_get(id,out,20,&count,&pending)==ESP_ERR_NOT_FOUND);assert(saves==0);}
static void *serial_thread(void *p){*(int *)p=zam_wifi_set_mode(ZAM_WIFI_AP);return NULL;}
static void *web_thread(void *p){zam_wifi_sta_request_t r=request(1);*(int *)p=zam_wifi_configure_sta(&r);return NULL;}
static void concurrent_test(void){for(int i=0;i<100;i++){reset();int a=-1,b=-1;pthread_t x,y;assert(!pthread_create(&x,NULL,serial_thread,&a));assert(!pthread_create(&y,NULL,web_thread,&b));assert(!pthread_join(x,NULL));assert(!pthread_join(y,NULL));assert((a==ESP_OK && b==ESP_ERR_INVALID_STATE)||(b==ESP_OK && a==ESP_ERR_INVALID_STATE));run();assert(saves==1);}}
int main(void){configure_test();scan_test();concurrent_test();puts("Wi-Fi worker configuration and scan host tests PASS");return 0;}
